import { useState } from 'react';
import type { NativeStackScreenProps } from '@react-navigation/native-stack';
import {
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';

import type { RootStackParamList } from '../navigation/types';
import { useAuth } from '../session/AuthContext';
import { theme } from '../theme';

type Props = NativeStackScreenProps<RootStackParamList, 'Login'>;

type Palette = {
  bg: string;
  surface: string;
  accent: string;
  text: string;
  muted?: string;
  textMuted?: string;
  danger?: string;
};

const themeValue = theme as unknown as Palette & { colors?: Palette };
const colors = themeValue.colors ?? themeValue;
const mutedColor = colors.textMuted ?? colors.muted ?? '#8B9BB4';

function getErrorMessage(error: unknown) {
  return error instanceof Error ? error.message : 'Не удалось войти. Попробуйте ещё раз.';
}

export function LoginScreen({ navigation }: Props) {
  const { login } = useAuth();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const canSubmit = username.trim().length > 0 && password.length > 0 && !submitting;

  const handleSubmit = async () => {
    if (!canSubmit) return;
    setSubmitting(true);
    setError(null);

    try {
      await login({ username: username.trim(), password });
    } catch (caughtError) {
      setError(getErrorMessage(caughtError));
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      style={styles.screen}
    >
      <View style={styles.form}>
        <Text style={styles.logo}>Msngr</Text>
        <Text style={styles.subtitle}>Ваши люди всегда рядом</Text>
        <TextInput
          autoCapitalize="none"
          autoCorrect={false}
          onChangeText={setUsername}
          placeholder="Имя пользователя"
          placeholderTextColor={mutedColor}
          returnKeyType="next"
          style={styles.input}
          textContentType="username"
          value={username}
        />
        <TextInput
          autoCapitalize="none"
          onChangeText={setPassword}
          onSubmitEditing={() => void handleSubmit()}
          placeholder="Пароль"
          placeholderTextColor={mutedColor}
          returnKeyType="done"
          secureTextEntry
          style={styles.input}
          textContentType="password"
          value={password}
        />
        {error ? <Text style={styles.error}>{error}</Text> : null}
        <Pressable
          accessibilityRole="button"
          disabled={!canSubmit}
          onPress={() => void handleSubmit()}
          style={({ pressed }) => [
            styles.primaryButton,
            !canSubmit && styles.disabledButton,
            pressed && canSubmit && styles.pressedButton,
          ]}
        >
          {submitting ? (
            <ActivityIndicator color={colors.text} />
          ) : (
            <Text style={styles.primaryButtonText}>Войти</Text>
          )}
        </Pressable>
        <Pressable accessibilityRole="link" onPress={() => navigation.navigate('Register')}>
          <Text style={styles.link}>Нет аккаунта? Зарегистрироваться</Text>
        </Pressable>
      </View>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  screen: {
    backgroundColor: colors.bg,
    flex: 1,
    justifyContent: 'center',
    paddingHorizontal: 24,
  },
  form: { width: '100%' },
  logo: {
    color: colors.accent,
    fontSize: 42,
    fontWeight: '800',
    letterSpacing: -1.5,
    textAlign: 'center',
  },
  subtitle: {
    color: mutedColor,
    fontSize: 15,
    marginBottom: 36,
    marginTop: 8,
    textAlign: 'center',
  },
  input: {
    backgroundColor: colors.surface,
    borderRadius: 12,
    color: colors.text,
    fontSize: 16,
    height: 54,
    marginBottom: 12,
    paddingHorizontal: 16,
  },
  error: {
    color: colors.danger ?? '#FF6B6B',
    fontSize: 13,
    marginBottom: 12,
  },
  primaryButton: {
    alignItems: 'center',
    backgroundColor: colors.accent,
    borderRadius: 12,
    height: 52,
    justifyContent: 'center',
    marginTop: 4,
  },
  disabledButton: { opacity: 0.45 },
  pressedButton: { opacity: 0.8 },
  primaryButtonText: { color: colors.text, fontSize: 16, fontWeight: '700' },
  link: {
    color: colors.accent,
    fontSize: 14,
    marginTop: 22,
    paddingVertical: 8,
    textAlign: 'center',
  },
});
